# -*- coding: ascii -*-
"""Fiches de metadonnees des corpus (datation, transmission, sources) -> metadonnees_corpus.json.
Annees : negatives = av. J.-C. Chaque fourchette vient d'une source citee ; ce qui n'a pas pu etre
verifie est liste dans 'a_verifier'. accord : consensus / debattu / tres_incertain.
Usage : python build_metadonnees.py [sortie.json]"""
import json, sys

SORTIE = sys.argv[1] if len(sys.argv) > 1 else "metadonnees_corpus.json"
W = "https://en.wikipedia.org/wiki/"

def C(nom, d, f, acc, note=""):
    return {"nom": nom, "debut": d, "fin": f, "accord": acc, "note": note}

def P(auteur, d, f, note=""):
    return {"auteur": auteur, "debut": d, "fin": f, "note": note}

def S(titre, url):
    return {"titre": titre, "url": url}

def F(corpus, langue, comp, positions=(), couches=(), transmission=(), traduction="", a_verifier=(), sources=(), aliases=()):
    return {"corpus": corpus, "aliases": list(aliases), "langue_origine": langue,
            "composition": {"debut": comp[0], "fin": comp[1], "accord": comp[2], "note": comp[3]},
            "positions": list(positions), "couches": list(couches), "transmission": list(transmission),
            "traduction": traduction, "a_verifier": list(a_verifier), "sources": list(sources)}

